use semio_framework_job_context::{Generation,OperationId,RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use semio_framework_value::ValueError;
fn clock()->Option<u64>{Some(1)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128}}
#[test]
fn actual_source_prices_nested_work_and_keeps_the_partial_receiver(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let grant=stock();
 for (index,row) in corpus["cases"].as_array().unwrap().iter().enumerate(){
  let chunks:Vec<Vec<u8>>=serde_json::from_value(row["chunks"].clone()).unwrap();let total=chunks.iter().map(Vec::len).sum::<usize>();let mut caller=OriginalJobFixtureCaller::admit(OperationId(710+index as u64),Generation(1),grant,clock,100000,100000);let mut output=None;let before=caller.fuel_remaining();
  let policy=RetainedCloneGrant{maximum_copy_bytes:row["maximumCopy"].as_u64().unwrap()as usize,maximum_capacity_bytes:row["maximumCapacity"].as_u64().unwrap()as usize,..grant};
  let (result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(policy,|cx|cx.with_native_encoding(&mut output,|control,output|{control.begin_stage(0)?;for chunk in &chunks{control.scoped_stage(|control|{control.begin_stage(chunk.len())?;control.advance(chunk.len())})?;}control.begin_stage(total)?;*output=Some(control.allocate_vec(total)?);for chunk in &chunks{control.scoped_stage(|control|{control.begin_stage(chunk.len())?;control.advance(chunk.len())?;output.as_mut().unwrap().extend_from_slice(chunk);Ok::<(),ValueError>(())})?;}Ok(())})));
  assert_eq!(result.is_ok(),row["valid"].as_bool().unwrap());assert_eq!(before-caller.fuel_remaining()-2,row["expectedWork"].as_u64().unwrap());assert_eq!(output.as_ref().map_or(&[][..],Vec::as_slice),serde_json::from_value::<Vec<u8>>(row["expectedBytes"].clone()).unwrap());let capacity=output.as_ref().map_or(0,Vec::capacity);assert_eq!(capacity,row["expectedCapacity"].as_u64().unwrap()as usize);assert_eq!((heap.requested_bytes,heap.released_bytes),(capacity,0));assert_eq!(caller.receipt().retained_capacity_bytes,capacity);
  if let Err(error)=result{assert_eq!(error.retained_progress(),caller.receipt());}
  let (_,close)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,released_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);drop(output.take());Ok(())}).unwrap());assert_eq!((close.requested_bytes,close.released_bytes),(0,capacity));caller.retire(grant);
 }
 let bytes:Vec<u8>=serde_json::from_value(corpus["unwind"]["bytes"].clone()).unwrap();let mut caller=OriginalJobFixtureCaller::admit(OperationId(719),Generation(1),grant,clock,100000,100000);let mut output=None;
 let (panic,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||std::panic::catch_unwind(std::panic::AssertUnwindSafe(||caller.turn(grant,|cx|cx.with_native_encoding(&mut output,|control,output|{control.begin_stage(bytes.len())?;*output=Some(control.allocate_vec(bytes.len())?);control.advance(bytes.len())?;output.as_mut().unwrap().extend_from_slice(&bytes);panic!("original encoding unwind law")})))));
 assert!(panic.is_err());assert_eq!(caller.receipt().retained_capacity_bytes,corpus["unwind"]["expectedCapacity"].as_u64().unwrap()as usize);assert_eq!(caller.receipt().copied_bytes,corpus["unwind"]["expectedCopies"].as_u64().unwrap()as usize);assert!(heap.requested_bytes>=bytes.len());assert_eq!(output.as_ref().unwrap(),&bytes);caller.turn(grant,|cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,released_bytes:output.as_ref().unwrap().capacity(),..Default::default()})?;cx.consume_fuel(1);drop(output.take());Ok(())}).unwrap();
 let policy=RetainedCloneGrant{maximum_depth:corpus["depth"]["source"].as_u64().unwrap()as usize,..grant};let result=caller.turn(policy,|cx|cx.with_native_encoding(&mut output,|control,_|control.scoped_depth(corpus["depth"]["consumer"].as_u64().unwrap()as usize,|control|control.scoped_depth(corpus["depth"]["consumer"].as_u64().unwrap()as usize,|_|Ok::<(),ValueError>(())))));assert_eq!(result.is_ok(),corpus["depth"]["admitted"].as_bool().unwrap());assert!(output.is_none());caller.retire(grant);
}
